Definition MB_MAX : Z := 0x1fffffffffffffff.

Definition mbe := (Z * Z)%type.   (* [comment removed for export] *)

Fixpoint mb_cap (es : list mbe) : Z := match es with [] => 0 | e :: es' => snd e + mb_cap es' end.
(* [comment removed for export] *)
Definition mb_capi (es : list mbe) : Z := mb_cap (removelast es).
(* [comment removed for export] *)
Definition mb_lasta (b : Z) (es : list mbe) : Z := fst (last es (b + 8, 0)).
Definition mb_lasts (es : list mbe) : Z := snd (last es (0, 0)).

(* [comment removed for export] *)
Definition mb_full (es : list mbe) (insz : Z) : bool := insz =? mb_cap es.
Definition mb_out (b : Z) (es : list mbe) (insz : Z) : Z := if mb_full es insz then b + 8 else mb_lasta b es.
Definition mb_outpos (es : list mbe) (insz : Z) : Z := if mb_full es insz then 0 else insz - mb_capi es.

(* [comment removed for export] *)
Definition mb_geom (es : list mbe) : Prop := forall A y z C, es = A ++ y :: z :: C -> 2 * mb_cap A <= snd z.
Definition mb_ok (es : list mbe) (insz : Z) : Prop :=
  (es = [] -> insz = 0) /\ (es <> [] -> mb_capi es + 1 <= insz <= mb_cap es)
  /\ Forall (fun e => 512 <= snd e <= 2^31) es /\ mb_geom es.

(* [comment removed for export] *)
Definition mb_need (es : list mbe) (insz n : Z) : bool := mb_cap es <? insz + n.
Definition mb_grow (es : list mbe) (insz n : Z) : Z := Z.max (insz + n - mb_cap es) (Z.max 512 (2 * insz)).
Definition mb_put_es (es : list mbe) (insz n x : Z) : list mbe :=
  if mb_need es insz n then es ++ [(x, mb_grow es insz n)] else es.

(* [comment removed for export] *)
Definition mb_mid_out (b : Z) (es : list mbe) (insz x : Z) : Z := if mb_full es insz then x else mb_lasta b es.
Definition mb_mid_outend (es : list mbe) (insz n : Z) : Z :=
  if mb_need es insz n then insz + n - mb_cap es else mb_outpos es insz + n.
(* [comment removed for export] *)
Definition mb_bufs (b : Z) (es : list mbe) (insz n x : Z) : list (Z * Z) :=
  if mb_need es insz n then
    if mb_full es insz then [(x + 24, n)]
    else [(mb_lasta b es + 24 + mb_outpos es insz, mb_cap es - insz); (x + 24, insz + n - mb_cap es)]
  else [(mb_lasta b es + 24 + mb_outpos es insz, n)].

