Lemma mb_cap_app : forall es1 es2, mb_cap (es1 ++ es2) = mb_cap es1 + mb_cap es2.
Proof. induction es1 as [|e es1 IH]; intros es2; cbn; [lia|]. rewrite IH. lia. Qed.

Lemma mb_cap_snoc : forall es x s, mb_cap (es ++ [(x, s)]) = mb_cap es + s.
Proof. intros. rewrite mb_cap_app. cbn. lia. Qed.

Lemma mb_cap_ge0 : forall es, Forall (fun e => 512 <= snd e <= 2^31) es -> 0 <= mb_cap es.
Proof. induction es as [|e es IH]; intros F; cbn; [lia|]. pose proof (Forall_inv F). pose proof (IH (Forall_inv_tail F)). cbn in *. lia. Qed.

Lemma mb_cap_ge0' : forall es : list mbe, (forall x s, In (x, s) es -> 0 <= s) -> 0 <= mb_cap es.
Proof.
  induction es as [|[x s] es IH]; intros H; cbn; [lia|].
  pose proof (H x s (or_introl eq_refl)). assert (0 <= mb_cap es) by (apply IH; intros x' s' IN; apply (H x' s'); right; exact IN). lia.
Qed.

(* [comment removed for export] *)
Lemma mb_cap_mid_ge0 : forall (es A B C : list mbe), (forall x s, In (x, s) es -> 0 <= s) -> es = A ++ B ++ C -> 0 <= mb_cap B.
Proof.
  intros es A B C H E. apply mb_cap_ge0'. intros x s IN. apply (H x s). rewrite E. apply in_app_iff. right. apply in_app_iff. left. exact IN.
Qed.

Lemma mb_capi_snoc : forall es x s, mb_capi (es ++ [(x, s)]) = mb_cap es.
Proof. intros. unfold mb_capi. rewrite removelast_app by discriminate. cbn. rewrite app_nil_r. reflexivity. Qed.

Lemma mb_lasta_snoc : forall b es x s, mb_lasta b (es ++ [(x, s)]) = x.
Proof. intros. unfold mb_lasta. rewrite last_last. reflexivity. Qed.

Lemma mb_lasts_snoc : forall es x s, mb_lasts (es ++ [(x, s)]) = s.
Proof. intros. unfold mb_lasts. rewrite last_last. reflexivity. Qed.
