Lemma mb_es_snoc_inv : forall es : list mbe, es <> [] -> exists es0 x s, es = es0 ++ [(x, s)].
Proof.
  intros es NE. exists (removelast es). destruct (last es (0,0)) as [x s] eqn:E. exists x, s.
  rewrite <- E. apply app_removelast_last. exact NE.
Qed.

Lemma mb_geom_nil : mb_geom [].
Proof. intros A y z C E. destruct A; discriminate. Qed.

Lemma mb_geom_snoc : forall es x s, mb_geom es -> 2 * mb_capi es <= s -> mb_geom (es ++ [(x, s)]).
Proof.
  intros es x s G LE A y z C E.
  destruct C as [|c C'] using rev_ind.
  - (* [comment removed for export] *)
    assert (E' : es ++ [(x, s)] = (A ++ [y]) ++ [z]) by (rewrite E, <- app_assoc; reflexivity).
    apply app_inj_tail in E'. destruct E' as [Ees Ez]. subst z. cbn.
    rewrite Ees in LE. unfold mb_capi in LE. rewrite removelast_app in LE by discriminate.
    cbn in LE. rewrite app_nil_r in LE. exact LE.
  - assert (E' : es ++ [(x, s)] = (A ++ y :: z :: C') ++ [c]) by (rewrite E, <- !app_assoc; reflexivity).
    apply app_inj_tail in E'. destruct E' as [Ees _]. exact (G A y z C' Ees).
Qed.

Lemma mb_ok_nil : mb_ok [] 0.
Proof.
  split; [reflexivity|]. split; [intros K; exfalso; exact (K eq_refl)|]. split; [constructor| exact mb_geom_nil].
Qed.

Lemma In_removelast : forall {A} (l : list A) (u : A), In u (removelast l) -> In u l.
Proof.
  intros A l u Hu. destruct l as [|a l']; [exact Hu|].
  rewrite (app_removelast_last a (l:=a :: l')) by discriminate. apply in_app_iff. left. exact Hu.
Qed.

Lemma mb_capi_ge0 : forall es, Forall (fun e => 512 <= snd e <= 2^31) es -> 0 <= mb_capi es.
Proof.
  intros es F. unfold mb_capi. apply mb_cap_ge0. apply (proj2 (Forall_forall _ _)). intros u Hu.
  apply (proj1 (Forall_forall _ _) F u). apply In_removelast. exact Hu.
Qed.

Lemma mb_ok_bounds : forall es insz, mb_ok es insz -> 0 <= insz <= mb_cap es /\ 0 <= mb_capi es <= insz.
Proof.
  intros es insz (E0 & E1 & F & _). pose proof (mb_capi_ge0 es F) as C0. pose proof (mb_cap_ge0 es F) as C1.
  destruct es as [|e es'].
  - rewrite (E0 eq_refl). cbn. unfold mb_capi. cbn. lia.
  - specialize (E1 ltac:(discriminate)). lia.
Qed.

