(* [comment removed for export] *)
Lemma mb_full_nil : forall insz, mb_ok [] insz -> mb_full [] insz = true.
Proof. intros insz (E0 & _). unfold mb_full. rewrite (E0 eq_refl). reflexivity. Qed.

Lemma mb_need_of_full : forall es insz n, mb_full es insz = true -> 1 <= n -> mb_need es insz n = true.
Proof. intros es insz n FU N1. unfold mb_full, mb_need in *. apply Z.eqb_eq in FU. apply Z.ltb_lt. lia. Qed.

Lemma mb_bufs_total : forall b es insz n x,
  fold_right (fun bl acc => snd bl + acc) 0 (mb_bufs b es insz n x) = n.
Proof.
  intros. unfold mb_bufs. destruct (mb_need es insz n), (mb_full es insz); cbn; lia.
Qed.

