(* [comment removed for export] *)
Lemma mb_lnode : forall m hL L ls x, dl_ok hL L ls -> ALSCells m ls -> x ∈ hL :: L ->
  exists nd, ls !! x = Some nd /\ l_next nd = cnext hL L x /\ l_prev nd = cprev hL L x
             /\ rw_cells bsegs m x [C8 (wz (cnext hL L x)); C8 (wz (cprev hL L x))].
Proof.
  intros m hL L ls x DL LC IN. destruct (dl_lookup _ _ _ DL x IN) as (nd & Lx & N & P).
  exists nd. split; [exact Lx|]. split; [exact N|]. split; [exact P|].
  pose proof (ALSCells_lookup _ _ _ _ LC Lx) as C. unfold LNodeCells in C. rewrite N, P in C. exact C.
Qed.

(* [comment removed for export] *)
Lemma mb_root_node : forall m b (es : list mbe) ls, dl_ok (b + 8) (map fst es) ls -> ALSCells m ls ->
  rw_cells bsegs m (b + 8) [C8 (wz (lhead (b + 8) (map fst es))); C8 (wz (mb_lasta b es))].
Proof.
  intros m b es ls DL LC.
  destruct (mb_lnode m _ _ _ (b + 8) DL LC ltac:(rewrite elem_of_cons; left; reflexivity)) as (nd & _ & _ & _ & C).
  rewrite cnext_hd, cprev_hd in C.
  replace (llast (b + 8) (map fst es)) with (mb_lasta b es) in C; [exact C|].
  unfold mb_lasta, llast. clear. induction es as [|[x s] es IH] using rev_ind. { reflexivity. }
  rewrite map_app. cbn [map fst]. rewrite !last_last. reflexivity.
Qed.

(* [comment removed for export] *)
Lemma mb_elem_node : forall m b (es A B : list mbe) x s ls,
  dl_ok (b + 8) (map fst es) ls -> ALSCells m ls -> es = A ++ (x, s) :: B ->
  rw_cells bsegs m x [C8 (wz (lhead (b + 8) (map fst B))); C8 (wz (llast (b + 8) (map fst A)))].
Proof.
  intros m b es A B x s ls DL LC E.
  assert (IN : x ∈ (b + 8) :: map fst es).
  { rewrite elem_of_cons. right. rewrite E, map_app. cbn. rewrite elem_of_app, elem_of_cons. right; left; reflexivity. }
  destruct (mb_lnode m _ _ _ x DL LC IN) as (nd & _ & _ & _ & C).
  pose proof (dl_N _ _ _ DL) as N. rewrite E, map_app in N, C. cbn [map fst] in N, C.
  rewrite (cnext_at _ _ _ _ (nd_cons_tl _ _ N)), (cprev_at _ _ _ _ (nd_cons_tl _ _ N)) in C. exact C.
Qed.

(* [comment removed for export] *)
Lemma mb_ne_last : forall b (es A B : list mbe) x s, NoDup (map fst es) -> es = A ++ (x, s) :: B -> B <> [] -> x <> mb_lasta b es.
Proof.
  intros b es A B x s ND E BNE EQ.
  destruct (mb_es_snoc_inv B BNE) as (B0 & y & t & EB). rewrite EB in E.
  assert (EL : mb_lasta b es = y). { rewrite E. unfold mb_lasta. replace (A ++ (x, s) :: B0 ++ [(y, t)]) with ((A ++ (x, s) :: B0) ++ [(y, t)]) by (rewrite <- app_assoc; reflexivity). rewrite last_last. reflexivity. }
  rewrite EL in EQ. subst y. rewrite E, map_app in ND. cbn [map fst] in ND. rewrite map_app in ND. cbn [map fst] in ND.
  apply list.NoDup_app in ND. destruct ND as (_ & _ & ND). apply list.NoDup_cons in ND. destruct ND as [NI _].
  apply NI. rewrite elem_of_app, elem_of_cons. right; left; reflexivity.
Qed.

(* [comment removed for export] *)
Lemma lhead_map_fst : forall d (B : list mbe), B <> [] -> lhead d (map fst B) = fst (hd (0, 0) B).
Proof. intros d [|[x s] B] NE; [exfalso; exact (NE eq_refl)| reflexivity]. Qed.

Lemma lhead_map_fst_app : forall d (R T : list mbe), R <> [] -> lhead d (map fst (R ++ T)) = fst (hd (0, 0) R).
Proof. intros d [|[x s] R] T NE; [exfalso; exact (NE eq_refl)| reflexivity]. Qed.

(* [comment removed for export] *)
Lemma mb_lnode_cases : forall b (es : list mbe) ls a n, dl_ok (b + 8) (map fst es) ls -> mb_addr_ok b es ->
  ls !! a = Some n -> a = b + 8 \/ exists s, In (a, s) es.
Proof.
  intros b es ls a n DL AOK La. destruct DL as (N & DOM & _).
  assert (Ia : a ∈ (b + 8) :: map fst es) by (apply DOM; rewrite La; eexists; reflexivity).
  rewrite elem_of_cons in Ia. destruct Ia as [E|Ia]; [left; exact E| right].
  apply list_elem_of_In in Ia. apply in_map_iff in Ia. destruct Ia as ([a' s] & E & IN). cbn in E. subst a'.
  exists s. exact IN.
Qed.

