(* [comment removed for export] *)
Lemma AMBraw_transport_gen : forall W m m' b es out insz outpos outend,
  AMBraw m b es out insz outpos outend -> munch W m m' -> wmono bsegs m m' ->
  disjoint_from W b 64 -> (forall x, b <= x < b + 64 -> outside W (sh x)) ->
  (forall x s, In (x, s) es -> disjoint_from W x (mb_block_size s) /\ disjoint_from W (sh x) (nsh (mb_block_size s))) ->
