(* [comment removed for export] *)
Lemma AMBraw_transport : forall SP W m m' b es out insz outpos outend,
  AMBraw m b es out insz outpos outend -> munch W m m' -> wmono bsegs m m' -> stackW SP W ->
  AMBraw m' b es out insz outpos outend.
Proof.
  intros SP W m m' b es out insz outpos outend R MU WM SW.
  pose proof R as (ls & _ & _ & _ & _ & _ & AOK & _ & _).
  eapply AMBraw_transport_win; [exact R| exact MU| exact WM|].
  eapply Forall_impl; [| exact SW]. intros [l h] [K _]. cbn [fst snd] in K. apply mwin_stack; [exact AOK| exact K].
Qed.

(* [comment removed for export] *)
Definition mwin_fr (b : Z) (es : list mbe) (ff k : Z) (iv : Z * Z) : Prop :=
  mwin b es iv \/ (sh ff <= fst iv /\ snd iv <= sh ff + k).

