  AIMG_TOP <= ff -> ff mod 8 = 0 -> 0 <= k -> ff + 8 * k <= aceil ->
  (b + 64 <= ff \/ ff + 8 * k <= b) -> (forall x s, In (x, s) es -> x + mb_block_size s <= ff \/ ff + 8 * k <= x) ->
