Scheme kc__8 := Elimination for Corelib.Init.Logic.False Sort Prop.

(* [comment removed for export] *)
Lemma AMBraw_snoc_nil : forall W m m' b out insz outpos outend x g junk out' outend',
  AMBraw m b [] out insz outpos outend -> munch W m m' -> wmono bsegs m m' -> Forall awin W ->
  disjoint_from W b 8 ->
  rw_cells bsegs m' (b + 24) [C8 (wz out'); C8 (wz insz); C8 (wz 0); C8 (wz outpos); C8 (wz outend')] ->
  rw_cells bsegs m' (b + 8) [C8 (wz x); C8 (wz x)] ->
  rw_cells bsegs m' x [C8 (wz (b + 8)); C8 (wz (b + 8))] ->
  rw_cells bsegs m' (x + 16) [C8 (wz g); CB (Z.to_nat (mb_block_size g - 24)) junk] ->
  0 < x -> x mod 16 = 0 -> 0 <= g -> aapp x (mb_block_size g) -> addressable m' x (mb_block_size g) ->
  (x + mb_block_size g <= b \/ b + 64 <= x) ->
