Lemma AMBraw_snoc_cons : forall W m m' b (P : list mbe) xl sl out insz outpos outend x g junk out' outend',
  AMBraw m b (P ++ [(xl, sl)]) out insz outpos outend -> munch W m m' -> wmono bsegs m m' -> Forall awin W ->
  disjoint_from W b 8 ->
  (forall x' s', In (x', s') (P ++ [(xl, sl)]) -> disjoint_from W (x' + 16) (mb_block_size s' - 16)) ->
  (forall x' s', In (x', s') P -> disjoint_from W x' 16) ->
  rw_cells bsegs m' (b + 24) [C8 (wz out'); C8 (wz insz); C8 (wz 0); C8 (wz outpos); C8 (wz outend')] ->
  rw_cells bsegs m' (b + 8) [C8 (wz (fst (hd (0, 0) (P ++ [(xl, sl)])))); C8 (wz x)] ->
  rw_cells bsegs m' x [C8 (wz (b + 8)); C8 (wz xl)] ->
  rw_cells bsegs m' xl [C8 (wz x); C8 (wz (llast (b + 8) (map fst P)))] ->
  rw_cells bsegs m' (x + 16) [C8 (wz g); CB (Z.to_nat (mb_block_size g - 24)) junk] ->
  0 < x -> x mod 16 = 0 -> 0 <= g -> aapp x (mb_block_size g) -> addressable m' x (mb_block_size g) ->
  (x + mb_block_size g <= b \/ b + 64 <= x) ->
  (forall x' s', In (x', s') (P ++ [(xl, sl)]) -> x + mb_block_size g <= x' \/ x' + mb_block_size s' <= x) ->
